import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _polygon_to_list(polygon: Optional[List[float]]) -> List[float]:
    return list(polygon) if polygon else []


def _bounding_region_to_dict(region: Any) -> Dict[str, Any]:
    return {
        "page_number": getattr(region, "page_number", None),
        "polygon": _polygon_to_list(getattr(region, "polygon", None)),
    }


def _span_to_dict(span: Any) -> Dict[str, Any]:
    return {
        "offset": getattr(span, "offset", None),
        "length": getattr(span, "length", None),
    }


def _word_to_dict(word: Any) -> Dict[str, Any]:
    return {
        "content": getattr(word, "content", None),
        "confidence": getattr(word, "confidence", None),
        "span": _span_to_dict(getattr(word, "span", None)) if getattr(word, "span", None) else None,
        "polygon": _polygon_to_list(getattr(word, "polygon", None)),
    }


def _line_to_dict(line: Any) -> Dict[str, Any]:
    return {
        "content": getattr(line, "content", None),
        "spans": [_span_to_dict(s) for s in (getattr(line, "spans", None) or [])],
        "polygon": _polygon_to_list(getattr(line, "polygon", None)),
    }


def _selection_mark_to_dict(mark: Any) -> Dict[str, Any]:
    return {
        "state": getattr(mark, "state", None),
        "confidence": getattr(mark, "confidence", None),
        "span": _span_to_dict(getattr(mark, "span", None)) if getattr(mark, "span", None) else None,
        "polygon": _polygon_to_list(getattr(mark, "polygon", None)),
    }


def _page_to_dict(page: Any) -> Dict[str, Any]:
    return {
        "page_number": getattr(page, "page_number", None),
        "width": getattr(page, "width", None),
        "height": getattr(page, "height", None),
        "unit": getattr(page, "unit", None),
        "lines": [_line_to_dict(line) for line in (getattr(page, "lines", None) or [])],
        "words": [_word_to_dict(word) for word in (getattr(page, "words", None) or [])],
        "selection_marks": [
            _selection_mark_to_dict(mark) for mark in (getattr(page, "selection_marks", None) or [])
        ],
    }


def _cell_to_dict(cell: Any) -> Dict[str, Any]:
    return {
        "row_index": getattr(cell, "row_index", None),
        "column_index": getattr(cell, "column_index", None),
        "row_span": getattr(cell, "row_span", None),
        "column_span": getattr(cell, "column_span", None),
        "content": getattr(cell, "content", None),
        "kind": getattr(cell, "kind", None),
        "bounding_regions": [
            _bounding_region_to_dict(br) for br in (getattr(cell, "bounding_regions", None) or [])
        ],
        "spans": [_span_to_dict(s) for s in (getattr(cell, "spans", None) or [])],
    }


def _table_to_dict(table: Any) -> Dict[str, Any]:
    return {
        "row_count": getattr(table, "row_count", None),
        "column_count": getattr(table, "column_count", None),
        "cells": [_cell_to_dict(cell) for cell in (getattr(table, "cells", None) or [])],
        "bounding_regions": [
            _bounding_region_to_dict(br) for br in (getattr(table, "bounding_regions", None) or [])
        ],
        "spans": [_span_to_dict(s) for s in (getattr(table, "spans", None) or [])],
    }


def _paragraph_to_dict(paragraph: Any) -> Dict[str, Any]:
    role = getattr(paragraph, "role", None)
    if role is not None and hasattr(role, "value"):
        role = role.value
    return {
        "content": getattr(paragraph, "content", None),
        "role": role,
        "bounding_regions": [
            _bounding_region_to_dict(br) for br in (getattr(paragraph, "bounding_regions", None) or [])
        ],
        "spans": [_span_to_dict(s) for s in (getattr(paragraph, "spans", None) or [])],
    }


def _key_value_element_to_ref_list(elements: Optional[List[Any]]) -> List[Dict[str, Any]]:
    refs = []
    for el in elements or []:
        refs.append({
            "content": getattr(el, "content", None),
            "bounding_regions": [
                _bounding_region_to_dict(br) for br in (getattr(el, "bounding_regions", None) or [])
            ],
            "spans": [_span_to_dict(s) for s in (getattr(el, "spans", None) or [])],
        })
    return refs


def _key_value_pair_to_dict(kv: Any) -> Dict[str, Any]:
    key = getattr(kv, "key", None)
    value = getattr(kv, "value", None)
    return {
        "key": {
            "content": getattr(key, "content", None) if key else None,
            "bounding_regions": [
                _bounding_region_to_dict(br) for br in (getattr(key, "bounding_regions", None) or [])
            ] if key else [],
            "spans": [_span_to_dict(s) for s in (getattr(key, "spans", None) or [])] if key else [],
        },
        "value": {
            "content": getattr(value, "content", None) if value else None,
            "bounding_regions": [
                _bounding_region_to_dict(br) for br in (getattr(value, "bounding_regions", None) or [])
            ] if value else [],
            "spans": [_span_to_dict(s) for s in (getattr(value, "spans", None) or [])] if value else [],
            "elements": _key_value_element_to_ref_list(getattr(value, "elements", None)) if value else [],
        },
        "confidence": getattr(kv, "confidence", None),
    }


def _document_style_to_dict(style: Any) -> Dict[str, Any]:
    return {
        "is_handwritten": getattr(style, "is_handwritten", None),
        "confidence": getattr(style, "confidence", None),
        "spans": [_span_to_dict(s) for s in (getattr(style, "spans", None) or [])],
    }


def extract_document_layout(
    source: Union[str, bytes],
    *,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
    model_id: str = "prebuilt-layout",
    output_content_format: str = "text",
    pages: Optional[str] = None,
    locale: Optional[str] = None,
    string_index_type: str = "unicodeCodePoint",
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    analyze_kwargs: Dict[str, Any] = {
        "output_content_format": output_content_format,
        "string_index_type": string_index_type,
    }
    if pages:
        analyze_kwargs["pages"] = pages
    if locale:
        analyze_kwargs["locale"] = locale

    if isinstance(source, bytes):
        poller = client.begin_analyze_document(
            model_id=model_id,
            body=source,
            **analyze_kwargs,
        )
    elif isinstance(source, str):
        with open(source, "rb") as f:
            poller = client.begin_analyze_document(
                model_id=model_id,
                body=f,
                **analyze_kwargs,
            )
    else:
        raise TypeError("source must be a file path or bytes")

    result = poller.result()

    return {
        "provider": "azure-document-intelligence",
        "model_id": model_id,
        "api_version": getattr(result, "api_version", None),
        "content": getattr(result, "content", None),
        "pages": [_page_to_dict(page) for page in (getattr(result, "pages", None) or [])],
        "tables": [_table_to_dict(table) for table in (getattr(result, "tables", None) or [])],
        "paragraphs": [
            _paragraph_to_dict(paragraph) for paragraph in (getattr(result, "paragraphs", None) or [])
        ],
        "key_value_pairs": [
            _key_value_pair_to_dict(kv) for kv in (getattr(result, "key_value_pairs", None) or [])
        ],
        "styles": [_document_style_to_dict(style) for style in (getattr(result, "styles", None) or [])],
